        if(!java.util.Set.of("7cd8263884669ca6244d9dee5a66b20a350f1b1dbfea24f7cb9f852f6583a441","4262726768bb500fc3e570819d0fbd6e7cc4ea0ff2ea1323e435f1be24502188").contains(pin)||!name.matches("[A-Za-z0-9_.-]+\\.zip"))
