                GL11.glTexImage2D(GL11.GL_TEXTURE_2D,0,GL30.GL_R11F_G11F_B10F,Math.max(1,s.proof.width/2),s.proof.height,0,GL11.GL_RGB,GL11.GL_FLOAT,0L);
