                &&GL20.glGetVertexAttribi(location,GL20.GL_VERTEX_ATTRIB_ARRAY_NORMALIZED)==0
                &&GL20.glGetVertexAttribi(location,GL30.GL_VERTEX_ATTRIB_ARRAY_INTEGER)==0
